const script = String.raw`
const fs=require('fs'), cp=require('child_process'), path=require('path');
const dirs=fs.readdirSync('packages',{withFileTypes:true}).filter(e=>e.isDirectory()&&fs.existsSync(path.join('packages',e.name,'package.json'))).map(e=>'packages/'+e.name);
const entries=dirs.map(dir=>({dir,j:JSON.parse(fs.readFileSync(path.join(dir,'package.json'),'utf8'))}));
const byName=new Map(entries.map(e=>[e.j.name,e]));
const seen=new Set(), active=new Set(), order=[];
function visit(e){if(seen.has(e.j.name))return;if(active.has(e.j.name))return;active.add(e.j.name);for(const n of Object.keys(e.j.dependencies||{})){if(byName.has(n))visit(byName.get(n));}active.delete(e.j.name);seen.add(e.j.name);order.push(e);}
for(const e of entries)visit(e);
let failed=0;
for(const e of order){
 if(!e.j.scripts?.build){console.log('SKIP_BUILD\t'+e.j.name);continue;}
 const r=cp.spawnSync('npm',['run','build','--workspace',e.j.name],{encoding:'utf8'});
 console.log((r.status===0?'PASS_BUILD':'FAIL_BUILD')+'\t'+e.j.name);
 if(r.status!==0){failed++;const s=(r.stdout||'')+(r.stderr||'');console.log(s.split(/\r?\n/).slice(-16).join('\n'));}
}
console.log('BUILD_SUMMARY\tpackages='+entries.length+'\tfailed='+failed);
process.exit(failed?1:0);
`;
