 if(r.status===0)passed++; else {failed++;console.log(s.split(/\r?\n/).slice(-24).join('\n'));}
}
console.log('TEST_SUMMARY\tpackages='+dirs.length+'\tpassed='+passed+'\tfailed='+failed+'\tskipped='+skipped+'\tobserved_tests='+tests);
process.exit(failed?1:0);
`;
